from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row if v != 0)
    common = {v for v, _ in counts.most_common(2)}
    out = [row[:] for row in grid]
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if not color or color in common or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft(); cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx)); q.append((yy,xx))
            comps.append((color, min(y for y,x in cells), max(y for y,x in cells), min(x for y,x in cells), max(x for y,x in cells)))
    for i, a in enumerate(comps):
        col, t, b, l, r = a
        for d in comps[i+1:]:
            color, t2, b2, l2, r2 = d
            if color != col: continue
            if t == t2 and b == b2:
                lo, hi = sorted((r, l2)) if r < l2 else sorted((r2, l))
                if r < l2 or r2 < l:
                    for y in range(t, b+1):
                        for x in range(lo+1, hi):
                            if grid[y][x] == 0: out[y][x] = col
            if l == l2 and r == r2 and (b < t2 or b2 < t):
                lo, hi = sorted((b, t2)) if b < t2 else sorted((b2, t))
                for x in range(l, r+1):
                    for y in range(lo+1, hi):
                        if grid[y][x] == 0: out[y][x] = col
    return out
